def get_batch(self, type, BLOCK_SIZE=16, batch_size=16):
    if type == "train":
        data = self.train_data
    else:
        data = self.val_data

    offsets = torch.randint(
        0,
        len(data) - BLOCK_SIZE - 1,
        (batch_size,)
    )

    x = torch.stack([
        data[i:i + BLOCK_SIZE]
        for i in offsets
    ])

    y = torch.stack([
        data[i + 1:i + BLOCK_SIZE + 1]
        for i in offsets
    ])

    return x, y
